INSERT INTO `content_field_asset_description` VALUES (423716,102713,0,'language_textarea','a:2:{s:29:\"field_language_textfield_lang\";a:1:{i:0;a:1:{s:5:\"value\";s:2:\"et\";}}s:28:\"field_language_textarea_name\";a:1:{i:0;a:1:{s:5:\"value\";s:205:\"Lastiliigi liigid on kooskõlas ÜRO Euroopa Majanduskomisjoni soovitusega nr 21 „Lastiliikide, pakendite ja pakkematerjalide koodid” („Codes for types of cargo, packages and packaging materials”).\";}}}',999),(437892,76726,0,'language_textarea','a:2:{s:29:\"field_language_textfield_lang\";a:1:{i:0;a:2:{s:5:\"value\";s:2:\"nl\";s:14:\"_error_element\";s:74:\"field_asset_description][0][value][field_language_textfield_lang][0][value\";}}s:28:\"field_language_textarea_name\";a:1:{i:0;a:2:{s:5:\"value\";s:187:\"<p>De SLD standaard definieert een encoding die de WMS standaard uitbreidt en het mogelijk maakt om gebruikergedefinieerde symbolen en kleuren te gebruiken in geografische gegevens.</p>\r\n\";s:14:\"_error_element\";s:73:\"field_asset_description][0][value][field_language_textarea_name][0][value\";}}}',437894),(473754,138634,0,NULL,NULL,NULL),(485085,142975,0,NULL,NULL,NULL),(494792,64668,0,NULL,NULL,NULL),(494921,84572,0,NULL,NULL,NULL),(495802,58694,0,NULL,NULL,NULL),(497578,137647,0,NULL,NULL,NULL),(498122,59180,0,NULL,NULL,NULL),(498136,59183,0,NULL,NULL,NULL),(500786,55759,0,NULL,NULL,NULL),(502131,60208,0,NULL,NULL,NULL),(505025,55776,0,NULL,NULL,NULL),(505038,55826,0,NULL,NULL,NULL),(507914,150484,0,NULL,NULL,NULL),(509883,55858,0,NULL,NULL,NULL),(511414,148080,0,NULL,NULL,NULL),(511416,139286,0,NULL,NULL,NULL),(511417,108335,0,NULL,NULL,NULL),(511420,86331,0,NULL,NULL,NULL),(511422,86277,0,NULL,NULL,NULL),(511424,86261,0,NULL,NULL,NULL),(511426,86186,0,NULL,NULL,NULL),(511428,86062,0,'language_textarea','a:2:{s:29:\"field_language_textfield_lang\";a:1:{i:0;a:1:{s:5:\"value\";s:2:\"de\";}}s:28:\"field_language_textarea_name\";a:1:{i:0;a:1:{s:5:\"value\";s:18:\"German description\";}}}',12334),(511590,154143,0,NU