INSERT INTO `content_field_project_soft_features` VALUES (484565,68304,'<pre wrap=\"\">\r\nThe signature verification tool provides a Web Upload form for manual\r\ndocument uploading and a SOAP interface for automatic requests. If desired,\r\nthe tool creates a signed signature verification PDF report archiving the\r\nverification result.\r\n\r\nThe signature verification tool supports the following signature formats:\r\n</pre>\r\n<ul>\r\n	<li>\r\n		W3C XMLDSIG&nbsp;</li>\r\n	<li>\r\n		X.509 certificate verification</li>\r\n	<li>\r\n		Cryptographic Message Syntax (CMS)</li>\r\n	<li>\r\n		XML Advanced Electronic Signatures (XAdES)</li>\r\n	<li>\r\n		PDF Advanced Electronic Signatures (PAdES)</li>\r\n	<li>\r\n		CMS Advanced Electronic Signatures (CAdES)</li>\r\n	<li>\r\n		Secure/Multipurpose Internet Mail Extensions (S/MIME)</li>\r\n	<li>\r\n		PDF-AS Signatures</li>\r\n</ul>\r\n',2),(510082,49860,'<ul>\r\n	<li>\r\n		Use of security and reliability standards like WS-Security, XML Electronic Signatures, X.509 certificates</li>\r\n	<li>\r\n		Discovery capabilities using the SMP and SML components</li>\r\n	<li>\r\n		DNS-based endpoint discovery mechanism&nbsp;</li>\r\n	<li>\r\n		Support of the PEPPOL AS2 transport protocol and the PEPPOL Business Message Envelope (SBDH) - <em>find more information in the </em><a href=\"http://www.peppol.eu/ressource-library/technical-specifications/\"><em>OpenPEPPOL Migration Policy</em></a></li>\r\n	<li>\r\n		Support of EBMS3.0/AS4 protocol trough the Domibus gateway developped in collaboration with <a href=\"http://www.esens.eu/\">eSENS</a> and <a href=\"http://www.e-codex.eu/home.html\">e-CODEX</a> Large Scale Pilots</li>\r\n</ul>\r\n<p>&nbsp;</p>\r\n',2),(516171,27026,'<p>&nbsp;</p>\r\n<p style=\"border-style: initial; border-color: initial; font-size: 13px; \">GNU Health is a<strong style=\"border-style: initial; border-color: initial; font-size: 13px; \">&nbsp;free&nbsp;Health and Hospital Information System</strong>&nbsp;with the following functionality :</p>\r\n<ul style=\"border-style: initial; border-color: initial; font-size: 13px; \">\r\n	<li style=\"border-style: initial; border-color: initial; font-size: 13px; \">\r\n		Electronic Medical Record (EMR)</li>\r\n	<li style=\"border-style: initial; border-color: initial; font-size: 13px; \">\r\n		Hospital Information System (HIS)</li>\r\n	<li style=\"border-style: initial; border-color: initial; font-size: 13px; \">\r\n		Health Information System&nbsp;</li>\r\n</ul>\r\n',2);
/*!40000 ALTER TABLE `content_field_project_soft_features` ENABLE KEYS */;
UNLOCK TABLES;

