INSERT INTO `content_field_project_soft_future_plans` VALUES (484565,68304,'<pre wrap=\"\">\r\nPlease have a look at the forum and the documentation.</pre>\r\n',2),(510082,49860,'<ul>\r\n	<li>\r\n		Support for additional features that will come from the e-SENS L.S.P. such as :\r\n		<ul>\r\n			<li>\r\n				Implementation of Busdox DBXL specification</li>\r\n			<li>\r\n				Support for ETSI REM evidences</li>\r\n		</ul>\r\n	</li>\r\n</ul>\r\n<p>The team is currently working on the roadmap of the components for the coming years. More information will be available soon.</p>\r\n',2),(516171,27026,'<p>GNU Health next events are published here :<br />\r\n	<br />\r\n	<a href=\"http://health.gnu.org/events.html\" title=\"http://www.gnuhealth.org/events.html\">http://health.gnu.org</a></p>\r\n',2);
/*!40000 ALTER TABLE `content_field_project_soft_future_plans` ENABLE KEYS */;
UNLOCK TABLES;

