INSERT INTO `content_field_project_soft_public_admin` VALUES (484565,68304,'<pre wrap=\"\">\r\nOn the website of the <a href=\"http://www.digitales.oesterreich.gv.at/site/cob__28748/5250/default.aspx\">platform digital Austria</a> you can find\r\ndescriptions, contacts and links to selected applications of all members of\r\nthe platform digital Austria.</pre>\r\n',2),(510082,49860,'<p>CIPA e-Delivery is supported by the&nbsp;<a href=\"http://ec.europa.eu/isa/actions/01-trusted-information-exchange/1-6_1-19action_en.htm\">ISA programme</a>&nbsp;of the European Commission.</p>\r\n',2),(516171,27026,'<p>Jamaica Ministry of Health has chosen GNU Health nationwide as their Health Information System.</p>\r\n<p>Some other examples include Argentina and Laos who are using GNU Health in public health centers / hospitals.</p>\r\n',2);
