INSERT INTO `content_field_repository_description` VALUES (120494,63884,0,NULL,NULL,NULL),(120514,60158,0,NULL,NULL,NULL),(120518,56804,0,NULL,NULL,NULL),(120526,82307,0,'language_textarea','a:2:{s:29:\"field_language_textfield_lang\";a:1:{i:0;a:2:{s:5:\"value\";s:2:\"fr\";s:14:\"_error_element\";s:79:\"field_repository_description][0][value][field_language_textfield_lang][0][value\";}}s:28:\"field_language_textarea_name\";a:1:{i:0;a:2:{s:5:\"value\";s:301:\"<p>Guadalinex est un syst&egrave;me d&#39;exploitation &agrave; base Ubuntu et un ensemble d&#39;applications promus par le gouvernment d&#39;Andalousie (Espagne). Il est utilis&eacute; dans les &eacute;coles, biblioth&egrave;ques, centres pour les personnes ag&eacute;es, et centres Guadalinfo.</p>\r\n\";s:14:\"_error_element\";s:78:\"field_repository_description][0][value][field_language_textarea_name][0][value\";}}}',518682),(120526,82307,1,'language_textarea','a:2:{s:29:\"field_language_textfield_lang\";a:1:{i:0;a:2:{s:5:\"value\";s:2:\"es\";s:14:\"_error_element\";s:79:\"field_repository_description][0][value][field_language_textfield_lang][0][value\";}}s:28:\"field_language_textarea_name\";a:1:{i:0;a:2:{s:5:\"value\";s:12:\"<p>Hola!</p>\";s:14:\"_error_element\";s:78:\"field_repository_description][0][value][field_language_textarea_name][0][value\";}}}',518682),(341336,59110,0,NULL,NULL,NULL),(500136,70676,0,'language_textarea','a:2:{s:29:\"field_language_textfield_lang\";a:1:{i:0;a:1:{s:5:\"value\";s:2:\"sl\";}}s:28:\"field_language_textarea_name\";a:1:{i:0;a:1:{s:5:\"value\";s:392:\"Portal NIO (nacionalni interoperabilnostni okvir) predstavlja temelj interoperabilnostnega delovanja v Sloveniji. Organizacijam omogoča objavljanje standardov, postopkov in drugih informacij za interoperabilnost ter interoperabilnostnih izdelkov, pomembnih na nacionalni ravni. Spodbuja tudi objavljanje odprtih podatkov in aplikacij, razvitih ob ponovni uporabi informacij javnega sektorja.\";}}}',500138);
