INSERT INTO `node_type` VALUES ('advertisement','Advertisement','node','','',1,'Title',1,'Body',0,1,1,0,''),('advpoll_binary','Binary poll','advpoll','Vote for or against a number of choices.','',1,'Text of poll',1,'Description',0,0,1,1,'advpoll_binary'),('advpoll_ranking','Ranking poll','advpoll','Rank a number of choices.','',1,'Ranking question',1,'Description',0,0,1,1,'advpoll_ranking'),('analytical_model','Analytical model','isa_nifo','Analytical model','',0,'',1,'Description',0,0,1,1,'analytical_model'),('asset_node_reference','asset node reference','node','Content used for fields into asset release content type','',1,'Title',1,'Body',0,1,1,0,''),('asset_release','Interoperability Solution','features','','',1,'Name',1,'Description',0,0,0,1,'asset_release'),('blog','Blog','node','Content type used for blogs','',1,'Title',1,'Description',1,1,1,0,''),('case_epractice','Case','features','','',1,'Title',1,'Abstract',1,0,0,1,'case_epractice'),('catalogue_node','Header Catalogue','node','','',1,'Title',1,'Body',0,1,1,0,''),('checksum','Checksum','node','A value that allows validating the integrity of a file’s content. According to the SPDX\r\nspecification [SPDX] it is a complex type consisting of:\r\n the algorithm\r\n a checksum value.','',1,'Value',0,'',0,1,1,0,''),('community','Community','node','','',1,'Name',1,'Description',1,1,1,0,''),('contact_point','Contact point','node','','',1,'Title',1,'Address',0,1,1,0,''),('contexthelp','Context Help','node','This node type will be utilized to create contexthelp placeholders.','',1,'Title',1,'Body',0,1,1,0,''),('contexthelp_faq','ContextHelp FAQ','node','','',1,'Question',1,'Answer',0,1,1,0,''),('d8_collection','D8 Collection','features','','',1,'Title',1,'Description',0,0,0,1,'d8_collection'),('data_set','Data Set','node','ADMS SW Data set content. Used for metrics in Software Projects and Releases','',1,'Data Name (English)',0,'',0,1,1,0,''),('distribution','Distribution','node','','',1,'Name',1,'Description',0,1,1,0,''),('document','Document','node','','',1,'Title',1,'Description',0,1,1,0,''),('documentation','Documentation','node','','',1,'Title',1,'Body',0,1,1,0,''),('event','Event','node','','',1,'Title',1,'Description',1,1,1,0,''),('factsheet','Factsheet','node','A (country) factsheet is a possibility to publish a document specific to a country, and a factsheet topic (to categorize its content using taxonomies, tags...).','',1,'Title',1,'Description',1,1,1,0,''),('featured_catalogue','Featured Catalogue','node','','',1,'Title',1,'Body',0,1,1,0,''),('home_carousel','Home Carousel','node','','',1,'Title',1,'Body',0,1,1,0,''),('home_catalogue','Home Catalogue','node','A node that allows us to show carousel or banner on the home catalog','',1,'Title',1,'Body',0,1,1,0,''),('identifier','Identifier','node','','',1,'Title',1,'Body',0,1,1,0,''),('isa_camss_assessment','CAMSS Assessment','features','Use this content type to create new assessments.','',1,'Title',1,'Body',0,0,0,1,'isa_camss_assessment'),('language_textarea','language textarea','node','','',1,'Title',1,'Body',0,1,1,0,''),('language_textfield','language textfield','node','','',1,'Title',1,'Body',0,1,1,0,''),('legaldocument','Legal Document','node','Legal document','',1,'Title',1,'Body',0,1,1,0,''),('licence','Licence','node','','',1,'Name',1,'Description',0,1,1,0,''),('news','News','node','This content type is used to describe item news posted by any registered user in the public area','',1,'Title',1,'Description',1,1,1,0,''),('newsletter','Newsletter','node','A newsletter issue to be sent to subscribed email addresses.','',1,'Title',1,'Description',1,1,1,0,'simplenews'),('og_page','Custom Section','node','Allows the creation of static pages asociated to a organic group','',1,'Title',1,'Body',0,1,1,0,''),('page','Page','node','A <em>page</em>, similar in form to a <em>story</em>, is a simple method for creating and displaying information that rarely changes, such as an \"About us\" section of a website. By default, a <em>page</em> entry does not allow visitor comments and is not featured on the site\'s initial home page.','',1,'Title',1,'Body',0,1,1,0,'page'),('presentation','Presentation','node','','',1,'Title',1,'Description',0,1,1,0,''),('profile','Profile','node','A user profile built as content.','',1,'Title',0,'',0,1,1,0,'profile'),('project','Software','node','Content type for Software Projects acording to ADMS SW specification','',1,'Software Project (English)',1,'Description (English)',0,1,1,0,''),('project_issue','Issue','project_issue','An issue that can be tracked, such as a bug report, feature request, or task.','',1,'Title',1,'Body',0,0,1,1,'project_issue'),('project_project','Project','project_project','A project is something a group is working on. It can optionally have issue tracking, integration with revision control systems, releases, and so on.','',1,'Title',1,'Body',1,0,1,1,'project_project'),('project_release','Project release','project_release','A release of a project with a specific version number.','',1,'Title',1,'Body',0,0,1,1,'project_release'),('publisher','Publisher','node','','',1,'Publisher Name (English)',0,'',0,1,1,0,''),('repository','Repository','node','A repository is the Joinup implementation of the ADMS \"Repository\"-concept. It can contain any number of Assets.','',1,'Repository name',1,'Repository description',1,1,1,0,''),('software_identifier','Software Identifier','node','Complex type (based on the software identifying system in the ISO19770-2:2009 software\r\nidentification tag XML data structure [ISO19770-2]) consisting of:\r\n   a unique token within the regid domain of the tag creator and/or subdomain; and\r\n   a tag creator regid.','',1,'Tag Creator Regid',0,'',0,1,1,0,''),('software_project_agent','Software Project Agent','node','Contains the agent values from ADMS SW used in Software Project content type.','',1,'Agent Name (English)',0,'',0,1,1,0,''),('software_release_agent','Software Release Agent','node','Contains the used by value from ADMS SW. Used in Releases content type.','',1,'Agent Name (English)',0,'',0,1,1,0,''),('story','Story','node','A <em>story</em>, similar in form to a <em>page</em>, is ideal for creating and displaying content that informs or engages website visitors. Press releases, site announcements, and informal blog-like entries may all be created with a <em>story</em> entry. By default, a <em>story</em> entry is automatically featured on the site\'s initial home page, and provides the ability to post comments.','',1,'Title',1,'Body',0,1,1,0,'story'),('topic','Topic','node','A topic is a communication channel based on discussions around a theme (taxonomy forum)','',1,'Title',1,'Description',1,1,1,0,''),('video','Video','node','Videos make it possible to manage Web TV.','',1,'Title',1,'Description',1,1,1,0,''),('wiki','Wiki','node','This is the content type to describe a wiki','<p>Please enter a little description for the content of this wiki page</p>\r\n',1,'Title',1,'Description',1,1,1,0,'');
