rue\" id=\"R_B_1_no\" trigger=\"SUMTrigger,CHARTTrigger\" exec=\"countNo|B_4_10\"></value>\r\n                    <value name=\"#Not Applicable A\" disabled=\"true\" exec=\"countNA|N_4_10\"></value>\r\n                    <value name=\"#Not Applicable B\" disabled=\"true\" exec=\"countNA|B_4_10\"></value>\r\n                </values>\r\n            </criteria>\r\n\r\n            <criteria name=\"Maturity\">\r\n                <nr>R.2</nr>\r\n                <values>\r\n                    <options>\r\n                        <option>--</option>\r\n                        <option>Very low</option>\r\n                        <option>Low</option>\r\n                        <option>Moderate</option>\r\n                        <option>High</option>\r\n                        <option>Very high</option>\r\n                    </options>\r\n                    <value name=\"Automated Score A\" id=\"R_2_score\" trigger=\"AVGTrigger,CHARTTrigger\" exec=\"autoScore|N_11_17\" suffix=\"%\" disabled=\"true\"></value>\r\n                    <value name=\"Automated Score B\" id=\"R_B_2_score\" trigger=\"AVGTrigger,CHARTTrigger\" exec=\"autoScore|B_11_17\" suffix=\"%\" disabled=\"true\"></value>\r\n                    <value name=\"Knock-Out Criteria met A?\" id=\"R_2_KO\" class=\"R_KO\" exec=\"KOCritera|M_11_17\" trigger=\"EXECTrigger\" disabled=\"true\"></value>\r\n                    <value name=\"Knock-Out Criteria met B?\" id=\"R_B_2_KO\" class=\"R_B_KO\" exec=\"KOCritera|C_11_17\" trigger=\"EXECTrigger\" disabled=\"true\"></value>\r\n                    <value name=\"Evaluation\" type=\"self_select\"></value>\r\n                    <value name=\"Comments\"></value>\r\n                    <value name=\"CAMSS Assessment Strength A\" suffix=\"%\" id=\"R_2_strength\" trigger=\"AVGTrigger,CHARTTrigger\" exec=\"assessmentStrength|N_11_17\" disabled=\"true\"></value>\r\n                    <value name=\"CAMSS Assessment Strength B\" suffix=\"%\" id=\"R_B_2_strength\" trigger=\"AVGTri