-Out Criteria met B?\" id=\"R_B_3_KO\" class=\"R_B_KO\" exec=\"KOCritera|C_18_28\" trigger=\"EXECTrigger\" disabled=\"true\"></value>\r\n                    <value name=\"Evaluation\" type=\"self_select\"></value>\r\n                    <value name=\"Comments\"></value>\r\n                    <value name=\"CAMSS Assessment Strength A\" suffix=\"%\" id=\"R_3_strength\" trigger=\"AVGTrigger,CHARTTrigger\" exec=\"assessmentStrength|N_18_28\" disabled=\"true\"></value>\r\n                    <value name=\"CAMSS Assessment Strength B\" suffix=\"%\" id=\"R_B_3_strength\" trigger=\"AVGTrigger,CHARTTrigger\" exec=\"assessmentStrength|B_18_28\" disabled=\"true\"></value>\r\n                    <value name=\"#Yes A\" disabled=\"true\" id=\"R_3_yes\" trigger=\"SUMTrigger,CHARTTrigger\" exec=\"countYes|N_18_28\"></value>\r\n                    <value name=\"#Yes B\" disabled=\"true\" id=\"R_B_3_yes\" trigger=\"SUMTrigger,CHARTTrigger\" exec=\"countYes|B_18_28\"></value>\r\n                    <value name=\"#No A\" disabled=\"true\" id=\"R_3_no\" trigger=\"SUMTrigger,CHARTTrigger\" exec=\"countNo|N_18_28\"></value>\r\n                    <value name=\"#No B\" disabled=\"true\" id=\"R_B_3_no\" trigger=\"SUMTrigger,CHARTTrigger\" exec=\"countNo|B_18_28\"></value>\r\n                    <value name=\"#Not Applicable A\" disabled=\"true\" exec=\"countNA|N_18_28\"></value>\r\n                    <value name=\"#Not Applicable B\" disabled=\"true\" exec=\"countNA|B_18_28\"></value>\r\n                </values>\r\n            </criteria>\r\n            <criteria name=\"Intellectual property rights\">\r\n                <nr>R.4</nr>\r\n                <values>\r\n                    <options>\r\n                        <option>--</option>\r\n                        <option>Very low</option>\r\n                        <option>Low</option>\r\n                        <option>Moderate</option>\r\n                        <option>High</option>\r\n                        <option>Very high</option>\r\n                    </options>\r\n                    <value name=\"Automated Score A\" id=\"R_4_score\" trigger=\"AVGTrigger,CHARTTrigger\" exec=\"autoScore|N_29_57\" suffix=\"%\" disabled=\"true\"></value>\r\n                    <value name=\"Automated Score B\" id=\"R_B_4_score\" trigger=\"AVGTrigger,CHARTTrigger\" exec=\"autoScore|B_29_57\" suffix=\"%\" disabled=\"true\"></value>\r\n                    <value name=\"Knock-Out Criteria met A?\" id=\"R_4_KO\" class=\"R_KO\" exec=\"KOCritera|M_29_57\" trigger=\"EXECTrigger\" disabled=\"true\"></value>\r\n                    <value name=\"Knock-Out Criteria met B?\" id=\"R_B_4_KO\" class=\"R_B_KO\" exec=\"KOCritera|C_29_57\" trigger=\"EXECTrigger\" disabled=\"true\"></value>\r\n                    <value name=\"Evaluation\" type=\"self_select\"></value>\r\n                    <value name=\"Comments\"></value>\r\n                    <value name=\"CAMSS Assessment Strength A\" suffix=\"%\" id=\"R_4_strength\" trigger=\"AVGTrigger,CHARTTrigger\" exec=\"assessmentStrength|N_29_57\" disabled=\"true\"></value>\r\n                    <value name=\"CAMSS Assessment Strength B\" suffix=\"%\" id=\"R_B_4_strength\" trigger=\"AVGTrigger,CHARTTrigger\" exec=\"assessmentStrength|B_29_57\" disabled=\"true\"></value>\r\n                    <value name=\"#Yes A\" disabled=\"true\" id=\"R_4_yes\" trigger=\"SUMTrigger,CHARTTrigger\" exec=\"countYes|N_29_57\"></value>\r\n                    <value name=\"#Yes B\" disabled=\"true\" id=\"R_B_4_yes\" trigger=\"SUMTrigger,CHARTTrigger\" exec=\"countYes|B_29_57\"></value>\r\n                    <value name=\"#No A\" disabled=\"true\" id=\"R_4_no\" trigger=\"SUMTrigger,CHARTTrigger\" exec=\"countNo|N_29_57\"></value>\r\n                    <value name=\"#No B\" disabled=\"true\" id=\"R_B_4_no\" trigger=\"SUMTrigger,CHARTTrigger\" exec=\"countNo|B_29_57\"></value>\r\n                    <value name=\"#Not Applicable A\" disabled=\"true\" exec=\"countNA|N_29_57\"></value>\r\n                    <value name=\"#Not Applicable B\" disabled=\"true\" exec=\"countNA|B_29_57\"></value>\r\n                </values>\r\n            </criteria>\r\n            <criteria name=\"Overall score\">\r\n                <values>\r\n                    <options>\r\n                        <option>--</option>\r\n                        <option>Very low</option>\r\n                        <option>Low</option>\r\n                        <option>Moderate</option>\r\n                        <option>High</option>\r\n                        <option>Very high</option>\r\n                    </options>\r\n                    <value name=\"Automated Score A\" avg=\"R_1_score,R_2_score,R_3_score,R_4_score\" trigger=\"CHARTTrigger\" suffix=\"%\" id=\"R_total_score\" disabled=\"true\"></value>\r\n                    <value name=\"Automated Score B\" avg=\"R_B_1_score,R_B_2_score,R_B_3_score,R_B_4_score\" trigger=\"CHARTTrigger\" suffix=\"%\" id=\"R_B_total_score\" disabled=\"true\"></value>\r\n                    <value name=\"Knock-Out Criteria met A?\" class=\"hidden\"></value>\r\n                    <value name=\"Knock-Out Criteria met B?\" class=\"hidden\"></value>\r\n                    <value name=\"Evaluation\" type=\"self_select\"></value>\r\n                    <value name=\"Comments\"></value>\r\n                    <value name=\"CAMSS Assessment Strength A\" suffix=\"%\" trigger=\"CHARTTrigger\" avg=\"R_1_strength,R_2_strength,R_3_strength,R_4_strength\" id=\"R_total_strength\" disabled=\"true\"></value>\r\n                    <value name=\"CAMSS Assessment Strength B\" suffix=\"%\" trigger=\"CHARTTrigger\" avg=\"R_B_1_strength,R_B_2_strength,R_B_3_strength,R_B_4_strength\" id=\"R_B_total_strength\" disabled=\"true\"></value>\r\n                    <value name=\"#Yes A\" disabled=\"true\" trigger=\"CHARTTrigger\" class=\"hidden\" id=\"R_total_yes\" sum=\"R_1_yes,R_2_yes,R_3_yes,R_4_yes\"></value>\r\n                    <value name=\"#Yes B\" disabled=\"true\" trigger=\"CHARTTrigger\" class=\"hidden\" id=\"R_B_total_yes\" sum=\"R_B_1_yes,R_B_2_yes,R_B_3_yes,R_B_4_yes\"></value>\r\n                    <value name=\"#No A\" disabled=\"true\" trigger=\"CHARTTrigger\" class=\"hidden\" id=\"R_total_no\" sum=\"R_1_no,R_2_no,R_3_no,R_4_no\"></value>\r\n                    <value name=\"#No B\" disabled=\"true\" trigger=\"CHARTTrigger\" class=\"hidden\" id=\"R_B_total_no\" sum=\"R_B_1_no,R_B_2_no,R_B_3_no,R_B_4_no\"></value>\r\n                    <value name=\"#Not Applicable A\" disabled=\"true\" class=\"hidden\"></value>\r\n                    <value name=\"#Not Applicable B\" disabled=\"true\" class=\"hidden\"></value>\r\n                </values>\r\n            </criteria>\r\n        </category>\r\n        <category>\r\n            <criteria name=\"Proposed classification A\">\r\n                <values>\r\n                    <options>\r\n                        <option>Select one of the values on the cell below</option>\r\n                        <option>Discarded</option>\r\n                        <option>Observed</option>\r\n                        <option>Accepted</option>\r\n                        <option>Recommended</option>\r\n                        <option>Mandatory</option>\r\n                    </options>\r\n                    <value name=\"Proposed classification A\" type=\"self_select\" exec=\"proposedClassification|R_KO\"></value>\r\n                </values>\r\n            </criteria>\r\n            <criteria name=\"Justification for classification A\">\r\n                <values>\r\n                    <value name=\"Justification for classification A\"></value>\r\n                </values>\r\n            </criteria>\r\n            <criteria name=\"Legal impact/requirements of classification A\">\r\n                <values>\r\n                    <value name=\"Legal impact/requirements of classification A\"></value>\r\n                </values>\r\n            </criteria>\r\n        </category>\r\n        <category>\r\n            <criteria name=\"Proposed classification B\">\r\n                <values>\r\n                    <options>\r\n                        <option>Select one of the values on the cell below</option>\r\n                        <option>Discarded</option>\r\n                        <option>Observed</option>\r\n                        <option>Accepted</option>\r\n                        <option>Recommended</option>\r\n                        <option>Mandatory</option>\r\n                    </options>\r\n                    <value name=\"Proposed classification B\" type=\"self_select\" exec=\"proposedClassification|R_B_KO\"></value>\r\n                </values>\r\n            </criteria>\r\n            <criteria name=\"Justification for classification B\">\r\n                <values>\r\n                    <value name=\"Justification for classification B\"></value>\r\n                </values>\r\n            </criteria>\r\n            <criteria name=\"Legal impact/requirements of classification B\">\r\n                <values>\r\n                    <value name=\"Legal impact/requirements of classification B\"></value>\r\n                </values>\r\n            </criteria>\r\n        </category>\r\n        <chart title=\"Automated Score\" id=\"chart_1\">\r\n            <labels>Market acceptance,Coherence principle,Attributes,Requirements,Overall score</labels>\r\n            <datasets>\r\n                <dataset name=\"Automated Score A\">R_1_score,R_2_score,R_3_score,R_4_score,R_total_score</dataset>\r\n                <dataset name=\"Automated Score B\">R_B_1_score,R_B_2_score,R_B_3_score,R_B_4_score,R_B_total_score</dataset>\r\n            </datasets>\r\n        </chart>\r\n        <chart title=\"Yes / No\" id=\"chart_2\">\r\n            <labels>Market acceptance,Coherence principle,Attributes,Requirements</labels>\r\n            <datasets>\r\n                <dataset name=\"Yes A\">R_1_yes,R_2_yes,R_3_yes,R_4_yes</dataset>\r\n                <dataset name=\"No A\">R_1_no,R_2_no,R_3_no,R_4_no</dataset>\r\n                <dataset name=\"Yes B\">R_B_1_yes,R_B_2_yes,R_B_3_yes,R_B_4_yes</dataset>\r\n                <dataset name=\"No B\">R_B_1_no,R_B_2_no,R_B_3_no,R_B_4_no</dataset>\r\n            </datasets>\r\n        </chart>\r\n        <chart title=\"Automated Score / CAMSS Assessment Strength\" id=\"chart_3\">\r\n            <labels>Market acceptance,Coherence principle,Attributes,Requirements,Overall score</labels>\r\n            <datasets>\r\n                <dataset name=\"Automated Score A\">R_1_score,R_2_score,R_3_score,R_4_score,R_total_score</dataset>\r\n                <dataset name=\"CAMSS Assessment Strength A\">R_1_strength,R_2_strength,R_3_strength,R_4_strength,R_total_strength</dataset>\r\n                <dataset name=\"Automated Score B\">R_B_1_score,R_B_2_score,R_B_3_score,R_B_4_score,R_B_total_score</dataset>\r\n                <dataset name=\"CAMSS Assessment Strength B\">R_B_1_strength,R_B_2_strength,R_B_3_strength,R_B_4_strength,R_B_total_strength</dataset>\r\n            </datasets>\r\n        </chart>\r\n    </section>\r\n</scenario>\r\n',0),(36997,88,'MSP Profile','<?xml version=\"1.0\" encoding=\"UTF-8\"?>\r\n<scenario name=\"MSP Profile\">\r\n    <version>1.0</version>\r\n    <description>MSP Profile</description>\r\n    <section name=\"CAMSS Log\">\r\n        <category name=\"Information on the submitter\">\r\n            <criteria name=\"Name, First name\">\r\n                <nr>L.1</nr>\r\n                <description></description>\r\n                <values>\r\n                    <value name=\"response\" type=\"text\"></value>\r\n                </values>\r\n            </criteria>\r\n            <criteria name=\"Organisation\">\r\n                <nr>L.2</nr>\r\n                <description></description>\r\n                <values>\r\n                    <value name=\"response\" type=\"text\"></value>\r\n                </values>\r\n            </criteria>\r\n            <criteria name=\"Position / Role\">\r\n                <nr>L.3</nr>\r\n                <description></description>\r\n                <values>\r\n                    <value name=\"response\" type=\"text\"></value>\r\n                </values>\r\n            </criteria>\r\n            <criteria name=\"Contact Address\">\r\n                <nr>L.4</nr>\r\n                <description></description>\r\n                <values>\r\n                    <value name=\"response\" type=\"text\"></value>\r\n                </values>\r\n            </criteria>\r\n            <criteria name=\"Contact Phone number\">\r\n                <nr>L.5</nr>\r\n                <description></description>\r\n                <values>\r\n                    <value name=\"response\" type=\"text\"></value>\r\n                </values>\r\n            </criteria>\r\n            <criteria name=\"Contact email\">\r\n                <nr>L.6</nr>\r\n                <description></description>\r\n                <values>\r\n                    <value name=\"response\" type=\"text\"></value>\r\n                </values>\r\n            </criteria>\r\n            <criteria name=\"Date of submission\">\r\n                <nr>L.7</nr>\r\n                <description></description>\r\n                <values>\r\n                    <value name=\"response\" type=\"text\"></value>\r\n                </values>\r\n            </criteria>\r\n        </category>\r\n    </section>\r\n\r\n    <section name=\"CAMSS Proposal\">\r\n        <category name=\"Information on the submission\">\r\n            <criteria name=\"Title of the specification\">\r\n                <nr>P.1</nr>\r\n                <org>O</org>\r\n                <description>The term \"ICT specification\" is used in the Regulation 1025/2012, Article 13, for specifications in the field of ICT that have been identified following the process of assessment against the Requirements and criteria laid down in Annex II to the Regulation. The ‘specification’ (as it will be cited along the present submission form) may be a single one or a ‘coherent set’ of ICT specifications; in all the cases the identity (including version) of each single document needs to be clearly announced, e.g. in one attached document</description>\r\n                <values>\r\n                    <value name=\"response\" type=\"text\"></value>\r\n                </values>\r\n            </criteria>\r\n            <criteria name=\"Address where the version of the specification can be obtained/downloaded\">\r\n                <nr>P.2</nr>\r\n                <org></org>\r\n                <description></description>\r\n                <values>\r\n                    <value name=\"response\" type=\"text\"></value>\r\n                </values>\r\n            </criteria>\r\n            <criteria name=\"Name, identifier and website of the standard developing organisation (SDO) of the specification\">\r\n                <nr>P.3</nr>\r\n                <org>O</org>\r\n                <description>List the people and/or roles involved in the decision making process.</description>\r\n                <values>\r\n                    <options>\r\n                        <option>Select value from the list</option>\r\n                        <option>W3C (http://www.w3.org)</option>\r\n                        <option>OASIS (https://www.oasis-open.org/)</option>\r\n                        <option>IEEE (http://standards.ieee.org/)</option>\r\n                        <option>ETSI (http://www.etsi.org/)</option>\r\n                        <option>Other SDO</option>\r\n                    </options>\r\n                    <value name=\"response\" type=\"self_select\" id=\"P_3\" class=\"P_3\" trigger=\"IFTrigger,EXECTrigger\">0</value>\r\n                </values>\r\n            </criteria>\r\n            <criteria name=\"Other SDO\" visible=\"false\">\r\n                <nr></nr>\r\n                <org></org>\r\n                <description></description>\r\n                <values>\r\n                    <value name=\"response\" id=\"P_3_SDO\" type=\"text\" exec=\"P3Changed|P_3,5\" trigger=\"IFTrigger\">0</value>\r\n                </values>\r\n            </criteria>\r\n            <criteria name=\"Contact information/contact person (including email address and phone number) a.) for the organisation (optional) b.) for the specification submitted (optional)\">\r\n                <nr>P.4</nr>\r\n                <org>O</org>\r\n                <description></description>\r\n                <values>\r\n                    <value name=\"response\" type=\"text\"></value>\r\n                </values>\r\n            </criteria>\r\n            <criteria name=\"Describe the reason for the submission, the need and intended use for the specification\">\r\n                <nr>P.5</nr>\r\n                <org>O</org>\r\n                <description></description>\r\n                <values>\r\n                    <value name=\"response\" type=\"text\"></value>\r\n                </values>\r\n            </criteria>\r\n            <criteria name=\"Is any other evaluation of this specification known, e.g. by member states or European Commission projects? If so, provide a link to this evaluation and –if possible- attach the evaluation in in Annex 1 of this form.\">\r\n                <nr>P.6</nr>\r\n                <org>O</org>\r\n                <description></description>\r\n                <values>\r\n                    <value name=\"response\" type=\"text\"></value>\r\n                </values>\r\n            </criteria>\r\n            <criteria name=\"State whether this submission concerns: A) Identification of a new specification B) a revision of an already identified specification  C) a proposal to withdraw the identification of an already identified specification\">\r\n                <nr>P.7</nr>\r\n                <org>O</org>\r\n                <description></description>\r\n                <values>\r\n                    <value name=\"response\" type=\"text\"></value>\r\n                </values>\r\n            </criteria>\r\n            <criteria name=\"If P.7, Case B, applies: please provide information on backward and forward compatibility with the version already approved\">\r\n                <nr>P.8</nr>\r\n                <org>O</org>\r\n                <description></description>\r\n                <values>\r\n                    <value name=\"response\" type=\"text\"></value>\r\n                </values>\r\n            </criteria>\r\n            <criteria name=\"If P.7, Case C applies: explain why the ICT specification no longer complies with the requirements for identification or the reasons for its withdrawal\">\r\n                <nr>P.9</nr>\r\n                <org>O</org>\r\n                <description></description>\r\n                <values>\r\n                    <value name=\"response\" type=\"text\"></value>\r\n                </values>\r\n            </criteria>\r\n            <criteria name=\"Is the submitted ICT specification: A) the first ICT specification from this standards developing organisation B) an ICT specification coming from a SDO of which a specification has previously been identified and which has undergone the same development and approval processes in the organisation.\">\r\n                <nr>P.10</nr>\r\n                <org>O</org>\r\n                <description>If P.10 B applies please give information concerning the identified ICT specification(s).</description>\r\n                <values>\r\n                    <value name=\"response\" type=\"text\"></value>\r\n                </values>\r\n            </criteria>\r\n        </category>\r\n    </section>\r\n\r\n    <section name=\"CAMSS Consideration\">\r\n        <category name=\"Correctness\">\r\n            <description>The proposal for the assessment of technical specifications or standards is provided correctly and the necessary documentation is provided.</description>\r\n            <criteria name=\"Is the proposal information from previous tabpage correctly provided?\">\r\n                <nr>C.1</nr>\r\n                <org>O</org>\r\n                <description></description>\r\n                <values>\r\n                    <value name=\"(Yes/No)\" type=\"yes_no_select\" mandatory=\"true\"></value>\r\n                    <value name=\"Justification\" type=\"text\"></value>\r\n                </values>\r\n            </criteria>\r\n            <criteria name=\"Is the complete documentation provided for performing the assessment?\">\r\n                <nr>C.2</nr>\r\n                <org>O</org>\r\n                <description></description>\r\n                <values>\r\n                    <value name=\"(Yes/No)\" type=\"yes_no_select\" mandatory=\"true\"></value>\r\n                    <value name=\"Justification\" type=\"text\"></value>\r\n                </values>\r\n            </criteria>\r\n        </category>\r\n        <category name=\"Relevance\">\r\n            <description>The proposal for the assessment of technical specifications or standards falls within the relevant areas of the public administration.</description>\r\n            <criteria name=\"Is the functional area of application for the formal specification addressing interoperability and eGovernment?\">\r\n                <nr>C.3</nr>\r\n                <org></org>\r\n                <description></description>\r\n                <values>\r\n                    <value name=\"(Yes/No)\" type=\"yes_no_select\" mandatory=\"true\"></value>\r\n                    <value name=\"Justification\" type=\"text\"></value>\r\n                </values>\r\n            </criteria>\r\n            <criteria name=\"Is the formal specification meeting the business needs?\">\r\n                <nr>C.4</nr>\r\n                <org></org>\r\n                <description></description>\r\n                <values>\r\n                    <value name=\"(Yes/No)\" type=\"yes_no_select\" mandatory=\"true\"></value>\r\n                    <value name=\"Justification\" type=\"text\"></value>\r\n                </values>\r\n            </criteria>\r\n        </category>\r\n        <category name=\"Legislation and regulation\">\r\n            <description>The proposal for the assessment of technical specifications or standards falls within the relevant areas of the public administration.</description>\r\n            <criteria name=\"Is the formal specification not hampering the regulatory requirements for the area of application?\">\r\n                <nr>C.5</nr>\r\n                <org>O</org>\r\n                <description></description>\r\n                <values>\r\n                    <value name=\"(Yes/No)\" type=\"yes_no_select\" mandatory=\"true\"></value>\r\n                    <value name=\"Justification\" type=\"text\"></value>\r\n                </values>\r\n            </criteria>\r\n        </category>\r\n    </section>\r\n\r\n    <section name=\"CAMSS Assessment\">\r\n        <category name=\"Market acceptance\">\r\n            <description>The technical specifications have market acceptance and their implementations do not hamper interoperability with the implementations of existing European or international standards. Market acceptance can be demonstrated by operational examples of compliant implementations from different vendors.</description>\r\n            <subcategory>\r\n                <criteria name=\"Has the specification been used for different implementations by different vendors/suppliers?\">\r\n                    <nr>A.1</nr>\r\n                    <description></description>\r\n                    <values>\r\n                        <value name=\"KO\" type=\"yes_no_select\" class=\"M_3_5\" trigger=\"EXECTrigger\"></value>\r\n                        <value name=\"Response\" type=\"yes_no_na_select\" class=\"N_3_5\" trigger=\"EXECTrigger\"></value>\r\n                        <value name=\"Justification\" trigger=\"SETResponseYes\"></value>\r\n                        <value name=\"Quantification\"></value>\r\n                    </values>\r\n                </criteria>\r\n            </subcategory>\r\n            <subcategory>\r\n                <criteria name=\"Does the implementation of the specification hamper interoperability with the implementation of existing European or international standards?\">\r\n                    <nr>A.2</nr>\r\n                    <values>\r\n                        <value name=\"KO\" type=\"yes_no_select\" class=\"M_3_5\" trigger=\"EXECTrigger\"></value>\r\n                        <value name=\"Response\" type=\"yes_no_na_select\" class=\"N_3_5\" trigger=\"EXECTrigger\"></value>\r\n                        <value name=\"Justification\" trigger=\"SETResponseYes\"></value>\r\n                        <value name=\"Quantification\"></value>\r\n                    </values>\r\n                </criteria>\r\n            </subcategory>\r\n            <subcategory>\r\n                <criteria name=\"Are you aware of public references of the respective specification by public authorities (especially policies or in procurements)\">\r\n                    <nr>A.3</nr>\r\n                    <values>\r\n                        <value name=\"KO\" type=\"yes_no_select\" class=\"M_3_5\" trigger=\"EXECTrigger\"></value>\r\n                        <value name=\"Response\" type=\"yes_no_na_select\" class=\"N_3_5\" trigger=\"EXECTrigger\"></value>\r\n                        <value name=\"Justification\" trigger=\"SETResponseYes\"></value>\r\n                        <value name=\"Quantification\"></value>\r\n                    </values>\r\n                </criteria>\r\n            </subcategory>\r\n        </category>\r\n        <category name=\"Coherence principle\">\r\n            <description>The technical specifications are coherent as they do not conflict with European standards, that is to say they cover domains where the adoption of new European standards is not foreseen within a reasonable period, where existing standards have not gained market uptake or where these standards have become obsolete, and where the transposition of the technical specifications into European standardisation deliverables is not foreseen within a reasonable period.</description>\r\n            <subcategory>\r\n                <criteria name=\"Has the technical specification or standard been used in different industries, business sectors or functions?\">\r\n                    <nr>A.4</nr>\r\n                    <values>\r\n                        <value name=\"KO\" type=\"yes_no_select\" class=\"M_6_7\" trigger=\"EXECTrigger\"></value>\r\n                        <value name=\"Response\" type=\"yes_no_na_select\" class=\"N_6_7\" trigger=\"EXECTrigger\"></value>\r\n                        <value name=\"Justification\" trigger=\"SETResponseYes\"></value>\r\n                        <value name=\"Quantification\"></value>\r\n                    </values>\r\n                </criteria>\r\n            </subcategory>\r\n            <subcategory>\r\n                <criteria name=\"a/ Is the adoption of new European Standards which cover the same areas as the proposed specification (or standard) foreseen within a reasonable timeframe?\">\r\n                    <nr>A.5</nr>\r\n                    <description></description>\r\n                    <values>\r\n                        <value name=\"KO\" type=\"yes_no_select\" class=\"M_6_7\" trigger=\"EXECTrigger\"></value>\r\n                        <value name=\"Response\" type=\"yes_no_na_select\" class=\"N_6_7\" trigger=\"EXECTrigger\"></value>\r\n                        <value name=\"Justification\" trigger=\"SETResponseYes\"></value>\r\n                        <value name=\"Quantification\"></value>\r\n                    </values>\r\n                </criteria>\r\n            </subcategory>\r\n            <subcategory>\r\n                <criteria name=\"b/ Are there existing European standards with market uptake which cover the same areas as the proposed specification (or standard) being assessed?\">\r\n                    <nr></nr>\r\n                    <description></description>\r\n                    <values>\r\n                        <value name=\"KO\" type=\"yes_no_select\" trigger=\"EXECTrigger\"></value>\r\n                        <value name=\"Response\" type=\"yes_no_na_select\" trigger=\"EXECTrigger\"></value>\r\n                        <value name=\"Justification\" trigger=\"SETResponseYes\"></value>\r\n                        <value name=\"Quantification\"></value>\r\n                    </values>\r\n                </criteria>\r\n            </subcategory>\r\n            <subcategory>\r\n                <criteria name=\"c/ If yes, are the existing standards becoming obsolete?\">\r\n                    <nr></nr>\r\n                    <description></description>\r\n                    <values>\r\n                        <value name=\"KO\" type=\"yes_no_select\" trigger=\"EXECTrigger\"></value>\r\n                        <value name=\"Response\" type=\"yes_no_na_select\" trigger=\"EXECTrigger\"></value>\r\n                        <value name=\"Justification\" trigger=\"SETResponseYes\"></value>\r\n                        <value name=\"Quantification\"></value>\r\n                    </values>\r\n                </criteria>\r\n            </subcategory>\r\n        </category>\r\n        <category name=\"Attributes\">\r\n            <description>The technical specifications were developed by a non-profit making organisation which is a professional society, industry or trade association or any other membership organisation that within its area of expertise develops standards in the field of information and communication technologies and which is not a European, national or international standardisation body</description>\r\n            <subcategory>\r\n                <criteria name=\"Is the standards developing organisation a non-profit making organisation?\">\r\n                    <nr>A.6</nr>\r\n                    <description>For the ‘users’, the diversity of the end-users of the products implementing the technical specification or standard is addressed.</description>\r\n                    <values>\r\n                        <value name=\"KO\" type=\"yes_no_select\" class=\"M_8_13\" trigger=\"EXECTrigger\"></value>\r\n                        <value name=\"Response\" type=\"yes_no_na_select\" class=\"N_8_13\" trigger=\"EXECTrigger\"></value>\r\n                        <value name=\"Justification\" trigger=\"SETResponseYes\"></value>\r\n                        <value name=\"Quantification\"></value>\r\n                    </values>\r\n                </criteria>\r\n            </subcategory>\r\n            <subcategory name=\"Openness\">\r\n                <description>the technical specifications were developed on the basis of open decision-making accessible to all interested parties in the market or markets affected by the standard.</description>\r\n                <criteria name=\"Is participation in the creation process of the specification open to all interested parties (e.g. organisations, companies or individuals)?\">\r\n                    <nr>A.7</nr>\r\n                    <description>For the ‘interest groups’, the degree of support from different interest groups is addressed.</description>\r\n                    <values>\r\n                        <value name=\"KO\" type=\"yes_no_select\" class=\"M_8_13\" trigger=\"EXECTrigger\"></value>\r\n                        <value name=\"Response\" type=\"yes_no_na_select\" class=\"N_8_13\" trigger=\"EXECTrigger\"></value>\r\n                        <value name=\"Justification\" trigger=\"SETResponseYes\" if=\"P_3=\'W3C (http://www.w3.org)\', \'http://www.w3.org/participate/\', P_3=\'OASIS (https://www.oasis-open.org/)\', \'https://www.oasis-open.org/join/categories-dues\', P_3=\'IEEE (http://standards.ieee.org/)\', \'http://standards.ieee.org/membership/\', P_3=\'ETSI (http://www.etsi.org/)\', \'In the CEPT area - http://www.etsi.org/index.php/membership\', \'\'\"></value>\r\n                        <value name=\"Quantification\"></value>\r\n                    </values>\r\n                </criteria>\r\n            </subcategory>\r\n            <subcategory name=\"Consensus\">\r\n                <description>the decision-making process was collaborative and consensus based and did not favour any particular stakeholder. Consensus means a general agreement, characterised by the absence of sustained opposition to substantial issues by any important part of the concerned interests and by a process that involves seeking to take into account the views of all parties concerned and to reconcile any conflicting arguments. Consensus does not imply unanimity.</description>\r\n                <criteria name=\"Are the specifications approved in a decision making process which aims at reaching consensus?\">\r\n                    <nr>A.8</nr>\r\n                    <description></description>\r\n                    <values>\r\n                        <value name=\"KO\" type=\"yes_no_select\" class=\"M_8_13\" trigger=\"EXECTrigger\"></value>\r\n                        <value name=\"Response\" type=\"yes_no_na_select\" class=\"N_8_13\" trigger=\"EXECTrigger\"></value>\r\n                        <value name=\"Justification\" trigger=\"SETResponseYes\" if=\"P_3=\'W3C (http://www.w3.org)\', \'http://www.w3.org/Consortium/Process/#Consensus\', P_3=\'OASIS (https://www.oasis-open.org/)\', \'https://www.oasis-open.org/policies-guidelines/tc-process#voting\', P_3=\'IEEE (http://standards.ieee.org/)\', \'http://standards.ieee.org/develop/balloting.html\', P_3=\'ETSI (http://www.etsi.org/)\', \'ETSI’s standards-making process is based on consensus. Only when consensus cannot be achieved is a vote conducted in a Technical Committee - https://portal.etsi.org/Directives/ ETSI Directives Technical Working Procedures p104 1.7 Decission making\', \'\'\"></value>\r\n                        <value name=\"Quantification\"></value>\r\n                    </values>\r\n                </criteria>\r\n            </subcategory>\r\n            <subcategory name=\"Transparency\">\r\n                <description>(i) all information concerning technical discussions and decision making was archived and identified. (ii) information on new standardisation activities was widely announced through suitable and accessible means.  (iii) participation of all interested categories of interested stakeholders was sought with a view to achieving balance. (iv) consideration and response were given to comments by interested parties.</description>\r\n                <criteria name=\"Is relevant documentation of the development and approval process of the specification archived and identified?\">\r\n                    <nr>A.9</nr>\r\n                    <description></description>\r\n                    <values>\r\n                        <value name=\"KO\" type=\"yes_no_select\" class=\"M_8_13\" trigger=\"EXECTrigger\"></value>\r\n                        <value name=\"Response\" type=\"yes_no_na_select\" class=\"N_8_13\" trigger=\"EXECTrigger\"></value>\r\n                        <value name=\"Justification\" trigger=\"SETResponseYes\"></value>\r\n                        <value name=\"Quantification\"></value>\r\n                    </values>\r\n                </criteria>\r\n            </subcategory>\r\n            <subcategory>\r\n                <criteria name=\"Is information on (new) standardisation activities widely announced through suitable and accessible means?\">\r\n                    <nr>A.10</nr>\r\n                    <description></description>\r\n                    <values>\r\n                        <value name=\"KO\" type=\"yes_no_select\" class=\"M_8_13\" trigger=\"EXECTrigger\"></value>\r\n                        <value name=\"Response\" type=\"yes_no_na_select\" class=\"N_8_13\" trigger=\"EXECTrigger\"></value>\r\n                        <value name=\"Justification\" trigger=\"SETResponseYes\"></value>\r\n                        <value name=\"Quantification\"></value>\r\n                    </values>\r\n                </criteria>\r\n            </subcategory>\r\n            <subcategory>\r\n                <criteria name=\"All relevant stakeholders can formally appeal or raise objections to the development and approval of specifications?\">\r\n                    <nr>A.11</nr>\r\n                    <description></description>\r\n                    <values>\r\n                        <value name=\"KO\" type=\"yes_no_select\" class=\"M_8_13\" trigger=\"EXECTrigger\"></value>\r\n                        <value name=\"Response\" type=\"yes_no_na_select\" class=\"N_8_13\" trigger=\"EXECTrigger\"></value>\r\n                        <value name=\"Justification\" trigger=\"SETResponseYes\" if=\"P_3=\'W3C (http://www.w3.org)\', \'http://www.w3.org/Consortium/Process/#FormalObjection\', P_3=\'OASIS (https://www.oasis-open.org/)\', \'https://www.oasis-open.org/policies-guidelines/tc-process#OASISstandard\', P_3=\'IEEE (http://standards.ieee.org/)\', \'There is right to appeal http://standards.ieee.org/develop/policies/bylaws/sect5.html#5.4\', P_3=\'ETSI (http://www.etsi.org/)\', \'Objections are contemplated in the Board and Technical Working procedures https://portal.etsi.org/Directives/ ETSI Directives Board Working Procedures p79 Technical Working Procedures p94\', \'\'\"></value>\r\n                        <value name=\"Quantification\"></value>\r\n                    </values>\r\n                </criteria>\r\n            </subcategory>\r\n        </category>\r\n        <category name=\"Requirements\">\r\n            <description>The technical specifications meet the following requirements</description>\r\n            <subcategory name=\"Maintenance\">\r\n                <description>Ongoing support and maintenance of published specifications are guaranteed over a long period.</description>\r\n                <criteria name=\"Does the specification have a defined maintenance and support process?\">\r\n                    <nr>A.12</nr>\r\n                    <description></description>\r\n                    <values>\r\n                        <value name=\"KO\" type=\"yes_no_select\" class=\"M_14_20\" trigger=\"EXECTrigger\"></value>\r\n                        <value name=\"Response\" type=\"yes_no_na_select\" class=\"N_14_20\" trigger=\"EXECTrigger\"></value>\r\n                        <value name=\"Justification\" trigger=\"SETResponseYes\"></value>\r\n                        <value name=\"Quantification\"></value>\r\n                    </values>\r\n                </criteria>\r\n            </subcategory>\r\n            <subcategory name=\"Availability\">\r\n                <description>Specifications are publicly available for implementation and use on reasonable terms (including for a reasonable fee or free of charge).</description>\r\n                <criteria name=\"Is the specification publicly available for implementation and use on reasonable terms?\">\r\n                    <nr>A.13</nr>\r\n                    <description></description>\r\n                    <values>\r\n                        <value name=\"KO\" type=\"yes_no_select\" class=\"M_14_20\" trigger=\"EXECTrigger\"></value>\r\n                        <value name=\"Response\" type=\"yes_no_na_select\" class=\"N_14_20\" trigger=\"EXECTrigger\"></value>\r\n                        <value name=\"Justification\" trigger=\"SETResponseYes\"></value>\r\n                        <value name=\"Quantification\"></value>\r\n                    </values>\r\n                </criteria>\r\n            </subcategory>\r\n            <subcategory name=\"Intellectual Property Rights\">\r\n                <description>(IPR) essential to the implementation of specifications are licensed to applicants on a (fair) reasonable and non-discriminatory basis ((F)RAND), which includes, at the discretion of the intellectual property rightholder, licensing essential intellectual property without compensation.</description>\r\n                <criteria name=\"a/ Is the specification licensed on a (F)RAND basis?\">\r\n                    <nr>A.14</nr>\r\n                    <description></description>\r\n                    <values>\r\n                        <value name=\"KO\" type=\"yes_no_select\" class=\"M_14_20\" trigger=\"EXECTrigger\"></value>\r\n                        <value name=\"Response\" type=\"yes_no_na_select\" class=\"N_14_20\" trigger=\"EXECTrigger\"></value>\r\n                        <value name=\"Justification\" trigger=\"SETResponseYes\"></value>\r\n                        <value name=\"Quantification\"></value>\r\n                    </values>\r\n                </criteria>\r\n            </subcategory>\r\n            <subcategory>\r\n                <criteria name=\"b/ Is the specification licensed on a royalty-free basis?\">\r\n                    <nr></nr>\r\n                    <description></description>\r\n                    <values>\r\n                        <value name=\"KO\" type=\"yes_no_select\" class=\"M_14_20\" trigger=\"EXECTrigger\"></value>\r\n                        <value name=\"Response\" type=\"yes_no_na_select\" class=\"N_14_20\" trigger=\"EXECTrigger\"></value>\r\n                        <value name=\"Justification\" trigger=\"SETResponseYes\"></value>\r\n                        <value name=\"Quantification\"></value>\r\n                    </values>\r\n                </criteria>\r\n            </subcategory>\r\n            <subcategory name=\"Relevance\">\r\n                <description>(i) the <specifi></specifi>cations are effective and relevant; (ii) specifications need to respond to market needs and regulatory requirements.</description>\r\n                <criteria name=\"a/ Is the s pecification licensed on a (F)RAND basis?  b/ Is the specification licensed on a royalty-free basis?\">\r\n                    <nr>A.15</nr>\r\n                    <description></description>\r\n                    <values>\r\n                        <value name=\"KO\" type=\"yes_no_select\" class=\"M_14_20\" trigger=\"EXECTrigger\"></value>\r\n                        <value name=\"Response\" type=\"yes_no_na_select\" class=\"N_14_20\" trigger=\"EXECTrigger\"></value>\r\n                        <value name=\"Justification\" trigger=\"SETResponseYes\"></value>\r\n                        <value name=\"Quantification\"></value>\r\n                    </values>\r\n                </criteria>\r\n            </subcategory>\r\n            <subcategory>\r\n                <criteria name=\"b/ Is there evidence that the adoption of the specification positively impacts one or several of the following: organisational processes; the environment; the administrative burden; the disability support; cross-border services, public policy objectives and societal needs ?\">\r\n                    <nr></nr>\r\n                    <description></description>\r\n                    <values>\r\n                        <value name=\"KO\" type=\"yes_no_select\" class=\"M_14_20\" trigger=\"EXECTrigger\"></value>\r\n                        <value name=\"Response\" type=\"yes_no_na_select\" class=\"N_14_20\" trigger=\"EXECTrigger\"></value>\r\n                        <value name=\"Justification\" trigger=\"SETResponseYes\"></value>\r\n                        <value name=\"Quantification\"></value>\r\n                    </values>\r\n                </criteria>\r\n            </subcategory>\r\n            <subcategory name=\"Neutrality and stability\">\r\n                <description>(i) specifications whenever possible are performance oriented rather than based on design or descriptive characteristics; (ii) specifications do not distort the market or limit the possibilities for implementers to develop competition and innovation based upon them; (iii)  specifications are based on advanced scientific and technological developments.</description>\r\n                <criteria name=\"a/ Is the specification largely independent from specific vendor products?\">\r\n                    <nr>A.16</nr>\r\n                    <description></description>\r\n                    <values>\r\n                        <value name=\"KO\" type=\"yes_no_select\" class=\"M_14_20\" trigger=\"EXECTrigger\"></value>\r\n                        <value name=\"Response\" type=\"yes_no_na_select\" class=\"N_14_20\" trigger=\"EXECTrigger\"></value>\r\n                        <value name=\"Justification\" trigger=\"SETResponseYes\"></value>\r\n                        <value name=\"Quantification\"></value>\r\n                    </values>\r\n                </criteria>\r\n            </subcategory>\r\n            <subcategory>\r\n                <criteria name=\"b/ Is the specification largely independent from specific platforms or technologies?\">\r\n                    <nr></nr>\r\n                    <description></description>\r\n                    <values>\r\n                        <value name=\"KO\" type=\"yes_no_select\" class=\"M_14_20\" trigger=\"EXECTrigger\"></value>\r\n                        <value name=\"Response\" type=\"yes_no_na_select\" class=\"N_14_20\" trigger=\"EXECTrigger\"></value>\r\n                        <value name=\"Justification\" trigger=\"SETResponseYes\"></value>\r\n                        <value name=\"Quantification\"></value>\r\n                    </values>\r\n                </criteria>\r\n            </subcategory>\r\n            <subcategory name=\"Quality\">\r\n                <description>(i) the quality and level of detail are sufficient to permit the development of a variety of competing implementations of interoperable products and services; (ii) standardised interfaces are not hidden or controlled by anyone other than the organisations that adopted the technical specifications.</description>\r\n                <criteria name=\"Has the specification sufficient detail, consistency and completeness for the use and development of products and services?\">\r\n                    <nr>A.17</nr>\r\n                    <description></description>\r\n                    <values>\r\n                        <value name=\"KO\" type=\"yes_no_select\" class=\"M_14_20\" trigger=\"EXECTrigger\"></value>\r\n                        <value name=\"Response\" type=\"yes_no_na_select\" class=\"N_14_20\" trigger=\"EXECTrigger\"></value>\r\n                        <value name=\"Justification\" trigger=\"SETResponseYes\"></value>\r\n                        <value name=\"Quantification\"></value>\r\n                    </values>\r\n                </criteria>\r\n            </subcategory>\r\n        </category>\r\n    </section>\r\n\r\n    <section name=\"CAMSS Recommandation\">\r\n        <category name=\"\">\r\n            <criteria name=\"Type of specification\">\r\n                <nr>R.0</nr>\r\n                <values>\r\n                    <options>\r\n                        <option>--</option>\r\n                        <option>Very low</option>\r\n                        <option>Low</option>\r\n                        <option>Moderate</option>\r\n                        <option>High</option>\r\n                        <option>Very high</option>\r\n                    </options>\r\n                    <value name=\"Automated Score\"></value>\r\n                    <value name=\"Knock-Out\" class=\"hidden\"></value>\r\n                    <value name=\"Evaluation\" type=\"self_select\" class=\"hidden\"></value>\r\n                    <value name=\"Comments\" class=\"hidden\"></value>\r\n                    <value name=\"CAMSS Assessment Strength\" class=\"hidden\"></value>\r\n                    <value name=\"#Yes\" disabled=\"true\" class=\"hidden\"></value>\r\n                    <value name=\"#No\" disabled=\"true\" class=\"hidden\"></value>\r\n                    <value name=\"#Not Applicable\" disabled=\"true\" class=\"hidden\"></value>\r\n                </values>\r\n            </criteria>\r\n\r\n            <criteria name=\"Market acceptance\">\r\n                <nr>R.1</nr>\r\n                <values>\r\n                    <options>\r\n                        <option>--</option>\r\n                        <option>Very low</option>\r\n                        <option>Low</option>\r\n                        <option>Moderate</option>\r\n                        <option>High</option>\r\n                        <option>Very high</option>\r\n                    </options>\r\n                    <value name=\"Automated Score\" id=\"R_1_score\" trigger=\"AVGTrigger,CHARTTrigger\" exec=\"autoScore|N_3_5\" suffix=\"%\" disabled=\"true\"></value>\r\n                    <value name=\"Knock-Out\" id=\"R_1_KO\" class=\"R_KO\" exec=\"KOCritera|M_3_5\" trigger=\"EXECTrigger\" disabled=\"true\"></value>\r\n                    <value name=\"Evaluation\" type=\"self_select\"></value>\r\n                    <value name=\"Comments\"></value>\r\n                    <value name=\"CAMSS Assessment Strength\" suffix=\"%\" id=\"R_1_strength\" trigger=\"AVGTrigger,CHARTTrigger\" exec=\"assessmentStrength|N_3_5\" disabled=\"true\"></value>\r\n                    <value name=\"#Yes\" disabled=\"true\" id=\"R_1_yes\" trigger=\"SUMTrigger,CHARTTrigger\" exec=\"countYes|N_3_5\"></value>\r\n                    <value name=\"#No\" disabled=\"true\" id=\"R_1_no\" trigger=\"SUMTrigger,CHARTTrigger\" exec=\"countNo|N_3_5\"></value>\r\n                    <value name=\"#Not Applicable\" disabled=\"true\" exec=\"countNA|N_3_5\"></value>\r\n                </values>\r\n            </criteria>\r\n\r\n            <criteria name=\"Coherence principle\">\r\n                <nr>R.2</nr>\r\n                <values>\r\n                    <options>\r\n                        <option>--</option>\r\n                        <option>Very low</option>\r\n                        <option>Low</option>\r\n                        <option>Moderate</option>\r\n                        <option>High</option>\r\n                        <option>Very high</option>\r\n                    </options>\r\n                    <value name=\"Automated Score\" id=\"R_2_score\" trigger=\"AVGTrigger,CHARTTrigger\" exec=\"autoScore|N_6_7\" suffix=\"%\" disabled=\"true\"></value>\r\n                    <value name=\"Knock-Out\" id=\"R_2_KO\" class=\"R_KO\" exec=\"KOCritera|M_6_7\" trigger=\"EXECTrigger\" disabled=\"true\"></value>\r\n                    <value name=\"Evaluation\" type=\"self_select\"></value>\r\n                    <value name=\"Comments\"></value>\r\n                    <value name=\"CAMSS Assessment Strength\" suffix=\"%\" id=\"R_2_strength\" trigger=\"AVGTrigger,CHARTTrigger\" exec=\"assessmentStrength|N_6_7\" disabled=\"true\"></value>\r\n                    <value name=\"#Yes\" disabled=\"true\" id=\"R_2_yes\" trigger=\"SUMTrigger,CHARTTrigger\" exec=\"countYes|N_6_7\"></value>\r\n                    <value name=\"#No\" disabled=\"true\" id=\"R_2_no\" trigger=\"SUMTrigger,CHARTTrigger\" exec=\"countNo|N_6_7\"></value>\r\n                    <value name=\"#Not Applicable\" disabled=\"true\" exec=\"countNA|N_6_7\"></value>\r\n                </values>\r\n            </criteria>\r\n            <criteria name=\"Attributes\">\r\n                <nr>R.3</nr>\r\n                <values>\r\n                    <options>\r\n                        <option>--</option>\r\n                        <option>Very low</option>\r\n                        <option>Low</option>\r\n                        <option>Moderate</option>\r\n                        <option>High</option>\r\n                        <option>Very high</option>\r\n                    </options>\r\n                    <value name=\"Automated Score\" id=\"R_3_score\" trigger=\"AVGTrigger,CHARTTrigger\" exec=\"autoScore|N_8_13\" suffix=\"%\" disabled=\"true\"></value>\r\n                    <value name=\"Knock-Out\" id=\"R_3_KO\" class=\"R_KO\" exec=\"KOCritera|M_8_13\" trigger=